  "chart_id": "chart-07",
  "issues": [],
  "observations": [
    {
      "description": "交易额的币种和计量量级待确认。",
      "evidence": [
        "PNG 右侧色标标题为“交易额”，刻度仅显示 100、150、200、250、300。",
        "CSV 和 spec.data.values 仅提供城市、月份和交易额。北京 12 月的数值均为 316，且该格位于色标高值端。"
      ],
      "reason_unconfirmed": "用途说明、CSV 和源码均未定义币种或计量量级，无法确定应在色标上补充什么单位。"
    },
    {
      "description": "彩虹色标的明暗不随数值单调变化，扫视时容易把更亮的格子看成更高值。",
      "evidence": [
        "PNG 中，广州 12 月的 220 呈亮黄色，全图最高的北京 12 月 316 呈暗红色。对照右侧色标可以确认两者的高低。",
        "spec.encoding.color.scale.range 从深蓝经青色、黄色过渡到深红。"
      ],
      "reason_unconfirmed": "所给有效经验中没有直接约束热力图色标明暗顺序的条款，因此记录为可读性观察。"
    },
    {
      "description": "静态图支持定位明显高值，相近高值的精确区分依赖原始数据。",
      "evidence": [
        "CSV 与源码中，北京 6 月为 271，9 月为 269。PNG 中这两格均呈相近的橙红色，格内无数字。",
        "用途说明要求观察分布并找出交易额高的月份和城市。"
      ],
      "reason_unconfirmed": "需确认看板是否还要求对相近高值精确排序或读取具体金额。现有用途说明未明确这一精度要求，因此不判定违反 EXP-006。"
    }
  ]
}
